<?php $q=mysqli_query($koneksi,"SELECT a.*,k.namakategori FROM alat a LEFT JOIN kategori k ON k.idkategori=a.idkategori ORDER BY a.idalat DESC"); function fotoAlatAdmin($nama,$foto){$nama=strtolower((string)$nama);$pilihan=['laptop'=>'laptop_asus.jpg','komputer'=>'laptop_asus.jpg','proyektor'=>'proyektor_epson.jpg','projector'=>'proyektor_epson.jpg','kabel'=>'kabel_hdmi.jpg','hdmi'=>'kabel_hdmi.jpg','mouse'=>'mouse_wireless.jpg','kamera'=>'kamera.jpg','camera'=>'kamera.jpg','toolbox'=>'toolbox_set.jpg','bor'=>'toolbox_set.jpg','obeng'=>'toolbox_set.jpg'];$f=basename((string)$foto);if($f!==''&&$f!=='default.png'&&is_file(__DIR__.'/../../../assets/uploads/sarana/'.$f))return $f;foreach($pilihan as $kata=>$file){if(strpos($nama,$kata)!==false)return $file;}return 'toolbox_set.jpg';} ?><h2>Data Sarana</h2><a class="btn btn-primary mb-3" href="index.php?halaman=createalat">Tambah Sarana</a><table class="table table-bordered"><tr><th>ID</th><th>Foto</th><th>Nama</th><th>Kategori</th><th>Jumlah</th><th>Kondisi</th><th>Lokasi</th><th>Aksi</th></tr><?php while($r=mysqli_fetch_assoc($q)): ?><tr><td><?=$r['idalat']?></td><td><?php $fotoTampil=fotoAlatAdmin($r['namaalat'],$r['foto']??''); ?><img src="assets/uploads/sarana/<?=htmlspecialchars($fotoTampil,ENT_QUOTES,'UTF-8')?>" alt="Foto <?=htmlspecialchars($r['namaalat'],ENT_QUOTES,'UTF-8')?>" style="width:75px;height:55px;object-fit:cover;border-radius:6px" loading="lazy"></td><td><?=htmlspecialchars($r['namaalat'])?></td><td><?=htmlspecialchars($r['namakategori']??'-')?></td><td><?=$r['jumlah']?></td><td><?=$r['kondisi']?></td><td><?=htmlspecialchars($r['lokasi'])?></td><td><a class="btn btn-sm btn-warning" href="index.php?halaman=editalat&id=<?=$r['idalat']?>">Edit</a> <a class="btn btn-sm btn-danger" onclick="return confirm('Hapus?')" href="proses/prosesalat.php?aksi=hapus&id=<?=$r['idalat']?>">Hapus</a></td></tr><?php endwhile;?></table>